namespace BlazorNotifications.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data.
        _notifications.AddRange(
        [
            new(NextId(), "Welcome to the notification center!", DateTime.UtcNow.AddMinutes(-10)),
            new(NextId(), "Your profile has been updated.", DateTime.UtcNow.AddMinutes(-5)),
            new(NextId(), "New feature: dark mode is now available.", DateTime.UtcNow.AddMinutes(-2)),
        ]);
    }

    /// <summary>Returns all notifications available right now.</summary>
    public List<Notification> GetAll()
    {
        lock (_lock)
        {
            return [.. _notifications];
        }
    }

    /// <summary>Returns only notifications newer than the given id.</summary>
    public List<Notification> GetSince(int lastSeenId)
    {
        lock (_lock)
        {
            return _notifications.Where(n => n.Id > lastSeenId).ToList();
        }
    }

    /// <summary>
    /// Simulates new notifications arriving over time.
    /// Called internally by the service on a timer.
    /// </summary>
    public void GenerateFakeNotification()
    {
        string[] templates =
        [
            "Server CPU usage is at {0}%.",
            "User #{0} just signed up.",
            "Deployment #{0} completed successfully.",
            "Disk usage alert: {0}% full.",
            "Build #{0} passed all tests.",
        ];

        var rng = Random.Shared;
        var message = string.Format(
            templates[rng.Next(templates.Length)],
            rng.Next(1, 100));

        lock (_lock)
        {
            _notifications.Add(new(NextId(), message, DateTime.UtcNow));
        }
    }

    private int NextId() => _nextId++;
}

@page "/notifications"
@rendermode InteractiveServer
@implements IDisposable
@inject BlazorNotifications.Services.NotificationService NotificationService

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill ms-2">@notifications.Count</span>
</h1>

@if (notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group mt-3">
        @foreach (var n in notifications.OrderByDescending(x => x.Timestamp))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <div>@n.Message</div>
                <small class="text-muted ms-3 text-nowrap">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<BlazorNotifications.Services.Notification> notifications = new();
    private CancellationTokenSource? _cts;
    private int _lastSeenId;

    // Runs during SSR *and* on interactive reconnect.
    protected override void OnInitialized()
    {
        notifications = NotificationService.GetAll();
        _lastSeenId = notifications.Count > 0 ? notifications.Max(n => n.Id) : 0;
    }

    // Runs only once the circuit is live (interactive). NOT during SSR.
    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct).ConfigureAwait(false);

            // Simulate the remote source occasionally producing a new notification.
            NotificationService.GenerateFakeNotification();

            var newer = NotificationService.GetSince(_lastSeenId);
            if (newer.Count > 0)
            {
                _lastSeenId = newer.Max(n => n.Id);
                await InvokeAsync(() =>
                {
                    notifications.AddRange(newer);
                    StateHasChanged();
                });
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

